import json
import hmac
import hashlib

def parse_payment(raw_body, headers, secret, now):
    """Return an accepted payment in the billing worker's normalized format."""
    try:
        event = json.loads(raw_body.decode('utf-8'))
    except (json.JSONDecodeError, UnicodeDecodeError):
        raise InvalidNotification("Malformed JSON body")

    event_id = event.get("event_id")
    account_id = event.get("account_id")
    amount_minor = event.get("amount_minor")
    currency = event.get("currency")

    if not event_id or not isinstance(event_id, str):
        raise InvalidNotification("Missing or invalid event_id")
    if not account_id or not isinstance(account_id, str):
        raise InvalidNotification("Missing or invalid account_id")
    if not isinstance(amount_minor, int) or isinstance(amount_minor, bool) or amount_minor < 0:
        raise InvalidNotification("Invalid amount_minor")
    if not currency or not isinstance(currency, str) or len(currency) != 3 or not currency.isascii() or not currency.isupper():
        raise InvalidNotification("Invalid currency")

    if "X-Pay-Timestamp" not in headers:
        raise InvalidNotification("Missing X-Pay-Timestamp header")
    timestamp_str = headers["X-Pay-Timestamp"]
    try:
        timestamp = int(timestamp_str)
    except ValueError:
        raise InvalidNotification("Malformed X-Pay-Timestamp header")

    if abs(timestamp - now) > 300:
        raise InvalidNotification("Stale delivery")

    if "X-Pay-Signature" not in headers:
        raise InvalidNotification("Missing X-Pay-Signature header")
    sig_header = headers["X-Pay-Signature"]
    if sig_header.startswith("v1="):
        # v1 path: verify signature against body
        if hmac.compare_digest(hmac.new(secret, (timestamp_str + "." + raw_body).encode(), hashlib.sha256).hexdigest(), sig_header[3:]):
            return {
                "event_id": event_id,
                "account_id": account_id,
                "amount_minor": amount_minor,
                "currency": currency
            }
        raise InvalidNotification("Invalid v1 signature")
    else:
        # v0 path: check for X-Pay-Receipt header
        if "X-Pay-Receipt" not in headers:
            raise InvalidNotification("Missing receipt for legacy delivery")
        receipt_header = headers["X-Pay-Receipt"]
        if not receipt_header.startswith("r0="):
            raise InvalidNotification("Invalid X-Pay-Receipt format")
        v0_digest = receipt_header[3:]

        # Verify v0 receipt: HMAC over timestamp + "." + event_id
        if hmac.compare_digest(hmac.new(secret, (timestamp_str + "." + event_id).encode(), hashlib.sha256).hexdigest(), v0_digest):
            return {
                "event_id": event_id,
                "account_id": account_id,
                "amount_minor": amount_minor,
                "currency": currency
            }
        raise InvalidNotification("Invalid v0 receipt")
