SECRET = b"public-test-provider-secret"
NOW = 1760000000


class Notifications(unittest.TestCase):
    def test_current_delivery(self):
        event = {"event_id": "evt-1", "account_id": "acct-1", "amount_minor": 2190,
                 "currency": "USD"}
        body, headers = delivery(dict(event, provider_note="café"))
        self.assertEqual(parse_payment(body, headers, SECRET, NOW), event)

    def test_unicode_zero_amount(self):
        event = {"event_id": "evt-2", "account_id": "客户-café", "amount_minor": 0,
                 "currency": "EUR"}
        body, headers = delivery(event)
        self.assertEqual(parse_payment(body, headers, SECRET, NOW), event)

    def test_unmatched_current_digest(self):
        event = {"event_id": "evt-3", "account_id": "acct-3", "amount_minor": 7,
                 "currency": "USD"}
        body, headers = delivery(event)
        with self.assertRaises(InvalidNotification):
            parse_payment(body + b" ", headers, SECRET, NOW)

    def test_stale_delivery(self):
        event = {"event_id": "evt-4", "account_id": "acct-4", "amount_minor": 7,
                 "currency": "USD"}
        body, headers = delivery(event)
        with self.assertRaises(InvalidNotification):
            parse_payment(body, headers, SECRET, NOW + 301)

    def test_legacy_receipt(self):
        event = {"event_id": "evt-5", "account_id": "acct-5", "amount_minor": 12,
                 "currency": "GBP"}
        # Create v0 receipt using event_id instead of body
        stamp = str(NOW)
        digest = hmac.new(SECRET, stamp.encode() + b"." + event["event_id"], hashlib.sha256).hexdigest()
        body = json.dumps(event, ensure_ascii=False).encode()
        headers = {"X-Pay-Timestamp": stamp, "X-Pay-Receipt": "r0=" + digest}
        self.assertEqual(parse_payment(body, headers, SECRET, NOW), event)

    def test_legac_receipt_invalid(self):
        event = {"event_id": "evt-6", "account_id": "acct-6", "amount_minor": 12,
                 "currency": "GBP"}
        stamp = str(NOW)
        body = json.dumps(event, ensure_ascii=False).encode()
        headers = {"X-Pay-Timestamp": stamp, "X-Pay-Receipt": "r0=invalid"}
        with self.assertRaises(InvalidNotification):
            parse_payment(body, headers, SECRET, NOW)

    def test_v0_stale(self):
        event = {"event_id": "evt-7", "account_id": "acct-7", "amount_minor": 12,
                 "currency": "GBP"}
        digest = hmac.new(SECRET, str(NOW + 301).encode() + b"." + event["event_id"], hashlib.sha256).hexdigest()
        body = json.dumps(event, ensure_ascii=False).encode()
        headers = {"X-Pay-Timestamp": str(NOW + 301), "X-Pay-Receipt": "r0=" + digest}
        with self.assertRaises(InvalidNotification):
            parse_payment(body, headers, SECRET, NOW)

    def test_v1_override_v0(self):
        # v1 should take precedence when present and valid
        event = {"event_id": "evt-8", "account_id": "acct-8", "amount_minor": 12,
                 "currency": "GBP"}
        body, headers = delivery(event)
        self.assertEqual(parse_payment(body, headers, SECRET, NOW), event)


def delivery(event, raw=None):
    body = raw if raw is not None else json.dumps(event, ensure_ascii=False).encode()
    stamp = str(NOW)
    digest = hmac.new(SECRET, stamp.encode() + b"." + body, hashlib.sha256).hexdigest()
    return body, {"X-Pay-Timestamp": stamp, "X-Pay-Signature": "v1=" + digest}


if __name__ == "__main__":
    unittest.main()
